mapper.select:
SELECT COALESCE(MAX(entitlement_version), 0) + 1
FROM iam_tenant_permission_entitlement
WHERE tenant_id = #{tenantId}

mapper.insert:
INSERT INTO iam_tenant_permission_entitlement (
    tenant_id, init_template_code, permission_id, entitlement_version,
    is_enabled, created_by, updated_by
)
SELECT #{tenantId}, #{initTemplateCode}, #{permissionId}, #{entitlementVersion},
       true, #{operator}, #{operator}
WHERE NOT EXISTS (
    SELECT 1
    FROM iam_tenant_permission_entitlement existing
    WHERE existing.tenant_id = #{tenantId}
      AND existing.permission_id = #{permissionId}
      AND existing.deleted_at IS NULL
)
